// ===================== SETTINGS =====================
// Your channel's niche. The agents will ONLY make videos inside this niche.
const NICHE = `Rise and fall stories of famous companies and brands: why giants collapsed, how underdogs beat them, surprising comebacks, bold strategies that paid off, and the business lessons behind each story.`;

// The point of view every video is told from. Edit this so it's true about you.
const CHANNEL_PERSPECTIVE = `The host is a young entrepreneur who builds AI automation for small businesses. They look at every story through practical lessons that small business owners, freelancers and new founders can apply today, and they are honest about mistakes instead of glorifying billionaires.`;

const APPROVER_EMAIL = 'you@gmail.com';     // where approval emails go
const MODEL = 'gemini-flash-latest';        // Gemini model
const VOICE = 'en-US-AndrewNeural';         // JSON2Video voice name
// ====================================================
const f = $input.first().json;
const after = String(f['After I approve'] || 'Publish publicly');
return [{ json: {
  settings: { NICHE, CHANNEL_PERSPECTIVE, APPROVER_EMAIL, MODEL, VOICE },
  topic: String(f['Topic'] || '').trim(),
  angle: '',
  isShort: String(f['Format'] || '').startsWith('Short'),
  yourTake: String(f['Your take'] || '').trim(),
  privacy: after.startsWith('Publish') ? 'public' : after.startsWith('Unlisted') ? 'unlisted' : 'private'
} }];

const s = $input.first().json;
const data = $getWorkflowStaticData('global');
const past = (data.pastTopics || []).slice(-80);
const today = new Date().toISOString().slice(0, 10);

const prompt = `You are the Topic Scout for an English YouTube channel. Today is ${today}.

CHANNEL NICHE (stay strictly inside it): ${s.settings.NICHE}

Pick ONE topic for a ${s.isShort ? 'YouTube Short (under 60 seconds, so focus on one single surprising moment or fact)' : 'long video (8-10 minutes, a full story with a clear arc)'}.

Use Google Search to choose a topic that is likely to get many views:
- a company or brand most people recognise (people click on names they know)
- a dramatic story arc: big rise, shocking fall, unlikely comeback, or a rivalry
- bonus if it is connected to something in the news right now
- enough reliable facts and numbers are available online
- prefer a fresh angle over a story big channels have covered in the exact same way

Never pick any of these topics, which the channel already covered: ${past.length ? past.join('; ') : 'none yet'}

Return ONLY a JSON object, no other text: {"topic": "the specific video topic", "angle": "the specific angle that makes it interesting", "why": "one sentence on why viewers will click"}`;

return [{ json: { ...s, model: s.settings.MODEL, requestBody: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  tools: [{ google_search: {} }],
  generationConfig: { temperature: 1.0 }
} } }];

const res = $input.first().json;
const s = $('Settings').first().json;
const raw = ((res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || []).map(p => p.text || '').join('');
let obj;
try {
  obj = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
} catch (e) {
  throw new Error('Topic Scout reply could not be read: ' + raw.slice(0, 400));
}
if (!obj.topic) throw new Error('Topic Scout did not return a topic.');
return [{ json: { ...s, topic: String(obj.topic), angle: String(obj.angle || '') } }];

const s = $input.first().json;

// Remember topics so the channel never repeats itself (saved when the workflow is Active)
const data = $getWorkflowStaticData('global');
data.pastTopics = [...(data.pastTopics || []), s.topic].slice(-150);

const prompt = `You are the Researcher for a YouTube channel in this niche: ${s.settings.NICHE}

Topic: ${s.topic}
${s.angle ? 'Angle: ' + s.angle : ''}

Use Google Search thoroughly. Prefer reliable sources: company reports and filings, major business news outlets, founder interviews and respected analysts. Write a research brief with these sections:
1. SUMMARY - the story in 3-4 sentences.
2. BACKGROUND - founding, founders, original idea and market.
3. TIMELINE - key events with dates, in order.
4. KEY NUMBERS - revenue, profit or loss, valuation, users, market share, funding. Give the year for every number and the source.
5. THE TURNING POINT.
6. WHAT WENT RIGHT / WRONG AND WHY - with expert or analyst reasoning where available.
7. COMPETITORS AND MARKET CONTEXT.
8. SURPRISING FACTS.
9. DISPUTED OR UNCERTAIN CLAIMS.
10. LESSONS for business owners.

Only include facts you found in sources. Never invent numbers, quotes or dates.`;

return [{ json: { ...s, model: s.settings.MODEL, requestBody: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  tools: [{ google_search: {} }],
  generationConfig: { temperature: 0.3 }
} } }];

const res = $input.first().json;
const s = $('Prepare Research').first().json;
const cand = res.candidates && res.candidates[0];
const research = ((cand && cand.content && cand.content.parts) || []).map(x => x.text || '').join('');
if (!research) throw new Error('Researcher returned no text: ' + JSON.stringify(res).slice(0, 500));

const seen = new Set();
const sources = [];
for (const c of ((cand.groundingMetadata && cand.groundingMetadata.groundingChunks) || [])) {
  const u = c.web && c.web.uri;
  if (u && !seen.has(u)) { seen.add(u); sources.push({ title: (c.web.title || 'source'), url: u }); }
}

const lengthRules = s.isShort
  ? 'This is a YouTube SHORT: 110-140 words in total, split into 6-8 scenes of 12-22 words each. The first scene is a strong hook. The last line is punchy or loops back to the start.'
  : 'This is a LONG video: 1,200-1,500 words in total (about 8-10 minutes), split into 35-55 scenes of 25-40 words each. Structure: hook (no greeting or channel intro), context, the rise, the turning point, the outcome, what we can learn, outro with one question for viewers.';

const prompt = `You are the Scriptwriter for an English YouTube channel that makes business case study videos.

Topic: ${s.topic}

${lengthRules}

Style: conversational, clear, short sentences, written to be spoken by a narrator. Build curiosity and tell it as a story. Avoid clichés like "In today's video", "buckle up", "game-changer", "let's dive in".

Use ONLY facts from the research brief. Never invent numbers, quotes or dates. Leave out anything the brief marks as uncertain.

${s.angle ? 'Angle: ' + s.angle : ''}

Channel point of view: ${s.settings.CHANNEL_PERSPECTIVE}
Tell the story from this point of view. In the lessons part, speak in first person as the host ("I think...", "What I find interesting...") and give a genuine opinion, not generic advice.
${s.yourTake ? 'The host\'s own opinion, which MUST be included naturally: "' + s.yourTake + '"' : ''}

For every scene, also write "search_query": 2-4 simple English words describing generic stock footage to show (for example "busy stock market screens", "factory assembly line", "person using smartphone"). Never use brand names, logos or real people's names in search_query, because stock sites don't have them.

Return ONLY a JSON object with these keys:
"title": under 70 characters, curiosity-driven, never misleading
"description": ${s.isShort ? '2-3 sentences' : '150-250 words, first two sentences contain the main keywords, end with a question for comments; no timestamps or links'}
"tags": array of 10-15 search phrases
"hashtags": array of 3 hashtags starting with #
"scenes": array of objects with "narration" and "search_query"

RESEARCH BRIEF:
${research}`;

return [{ json: { research, sources, model: s.model, requestBody: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.8, maxOutputTokens: 16384, responseMimeType: 'application/json' }
} } }];

const res = $input.first().json;
const s = $('Prepare Research').first().json;
const raw = ((res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || []).map(p => p.text || '').join('');
let script;
try {
  script = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
} catch (e) {
  throw new Error('Could not read the script from Gemini. Reply started with: ' + raw.slice(0, 400));
}
const scenes = (script.scenes || []).filter(x => x && x.narration);
if (scenes.length < 3) throw new Error('The script has too few scenes. Try running again.');

// Save the script details for later steps
const staticScript = { title: script.title, description: script.description, tags: script.tags || [], hashtags: script.hashtags || [] };

return scenes.map((sc, i) => ({ json: {
  index: i,
  narration: String(sc.narration).trim(),
  search_query: String(sc.search_query || s.topic).trim(),
  orientation: s.isShort ? 'portrait' : 'landscape',
  meta: i === 0 ? staticScript : null
} }));

const s = $('Prepare Research').first().json;
const scenes = $('Split Scenes').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const meta = scenes[0].meta;

function pickFile(video, portrait) {
  const files = (video.video_files || []).filter(f => (f.file_type || '').includes('mp4') && f.link);
  const ok = files.filter(f => {
    const long = Math.max(f.width || 0, f.height || 0);
    const isPortrait = (f.height || 0) > (f.width || 0);
    return long >= 1200 && long <= 2000 && isPortrait === portrait;
  });
  const list = ok.length ? ok : files.filter(f => Math.max(f.width || 0, f.height || 0) <= 2000);
  list.sort((a, b) => (b.width * b.height) - (a.width * a.height));
  return list[0] ? list[0].link : null;
}

const used = new Set();
const clips = [];
let lastGood = null;
scenes.forEach((sc, i) => {
  const videos = (results[i] && results[i].videos) || [];
  let chosen = null;
  for (const v of videos) {
    if (used.has(v.id)) continue;
    const link = pickFile(v, s.isShort);
    if (link) { chosen = link; used.add(v.id); break; }
  }
  clips.push(chosen);
  if (chosen) lastGood = chosen;
});
// Fill any scene without footage with the nearest clip that worked
const firstGood = clips.find(Boolean);
if (!firstGood) throw new Error('No stock footage found on Pexels. Check the Pexels API key.');
let prev = firstGood;
for (let i = 0; i < clips.length; i++) { if (clips[i]) prev = clips[i]; else clips[i] = prev; }

const movie = {
  resolution: s.isShort ? 'instagram-story' : 'full-hd',
  quality: 'high',
  scenes: scenes.map((sc, i) => ({
    elements: [
      { type: 'video', src: clips[i], loop: -1, duration: -2, volume: 0, resize: 'cover' },
      { type: 'voice', text: sc.narration, voice: s.settings.VOICE }
    ]
  })),
  elements: [{ type: 'subtitles', language: 'en' }]
};

// Prepare publishing details
let title = String(meta.title || s.topic).trim();
if (s.isShort && !/#shorts/i.test(title) && title.length + 8 <= 100) title += ' #Shorts';
title = title.slice(0, 100);
const hashtags = (meta.hashtags || []).map(String);
if (s.isShort && !hashtags.some(h => /#shorts/i.test(h))) hashtags.unshift('#Shorts');
const description = (String(meta.description || '') + '\n\n' + hashtags.join(' ')).slice(0, 4900);
let tags = [], total = 0;
for (const t of (meta.tags || [])) {
  const x = String(t).replace(/[<>,]/g, '').trim();
  if (!x || total + x.length + 1 > 450) continue;
  tags.push(x); total += x.length + 1;
}

return [{ json: {
  movie, title, description, tags: tags.join(','),
  narration: scenes.map(sc => sc.narration).join('\n\n')
} }];

const r = $input.first().json;
const m = r.movie || {};
const status = String(m.status || '').toLowerCase();
if (status === 'error' || r.success === false) {
  throw new Error('JSON2Video render failed: ' + (m.message || r.message || JSON.stringify(r).slice(0, 400)));
}
if (status === 'done' && m.url) return [{ json: { done: true, url: m.url } }];
if ($runIndex >= 45) throw new Error('Render is taking longer than 45 minutes. Check your JSON2Video dashboard.');
return [{ json: { done: false, status } }];

const s = $('Prepare Research').first().json;
const v = $('Build Video JSON').first().json;
const p = $('Prepare Script Prompt').first().json;
const url = $input.first().json.url;
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sources = p.sources.slice(0, 15).map(x => `<li><a href="${x.url}">${esc(x.title)}</a></li>`).join('');
const html = `<h2>New ${s.isShort ? 'Short' : 'video'} ready for review</h2>
<p><b><a href="${url}">▶ Watch the video</a></b></p>
<p><b>Title:</b> ${esc(v.title)}</p>
<p><b>After approval it will be uploaded as:</b> ${s.privacy}</p>
<p><b>Before approving, check:</b> the facts against the sources, that the footage matches the story, and that your opinion is in it.</p>
<h3>Description</h3><p>${esc(v.description).replace(/\n/g, '<br>')}</p>
<h3>Sources</h3><ul>${sources || '<li>No sources returned</li>'}</ul>
<h3>Full narration</h3><p>${esc(v.narration).replace(/\n/g, '<br>')}</p>`;
return [{ json: { url, html, email: s.settings.APPROVER_EMAIL, subject: 'Review: ' + v.title } }];
